boolean awaitHealthy(long timeout, TimeUnit unit) {
  if (monitor.enterWhenUninterruptibly(awaitHealthGuard, timeout, unit)) {
    try {
      monitor.leave();
    } catch (IllegalMonitorStateException e) {
      // 记录异常并确保程序不会因锁管理错误中断
      e.printStackTrace();
      return false;
    }
    return true;
  }
  return false;
}
